    "path": "lib\\core\\constants\\app_colors.dart",
    "description": "Central color palette; add colors used by the next screen UI.",
    "content": "import 'package:flutter/material.dart';\n\nclass AppColors {\n  AppColors._();\n\n  static const Color primary = Color(0xFF53B175);\n  static const Color onPrimary = Colors.white;\n  static const Color background = Colors.white;\n  static const Color surface = Colors.white;\n  static const Color textPrimary = Color(0xFF181725);\n  static const Color textSecondary = Color(0xFF7C7C7C);\n  static const Color border = Color(0xFFE2E2E2);\n  static const Color accentOrange = Color(0xFFF8A44C);\n  static const Color accentGreen = Color(0xFF53B175);\n  static const Color cardShadow = Color(0x17000000);\n  static const Color navInactive = Color(0xFF334355);\n  static const Color navActive = Color(0xFF5468FF);\n  static const Color bannerRed = Color(0xFFA74242);\n  static const Color chipGreen = Color(0xFFEAF8F0);\n  static const Color chipOrange = Color(0xFFFFF3E6);\n}\n"
