  {
    "path": "lib\\core\\constants\\app_dimensions.dart",
    "description": "Shared spacing and size helpers; apply for consistent next screen layout.",
    "content": "import 'package:flutter/material.dart';\nimport 'package:demo_app_2/core/utils/context_extensions.dart';\n\nclass AppDimensions {\n  AppDimensions._();\n\n  static double spacingXs(BuildContext context) => context.widthUnit * 1.5;\n  static double spacingSm(BuildContext context) => context.widthUnit * 2.5;\n  static double spacingMd(BuildContext context) => context.widthUnit * 4;\n  static double spacingLg(BuildContext context) => context.widthUnit * 6;\n  static double spacingXl(BuildContext context) => context.widthUnit * 8;\n\n  static double radiusSm(BuildContext context) => context.widthUnit * 2.5;\n  static double radiusMd(BuildContext context) => context.widthUnit * 3.5;\n  static double radiusLg(BuildContext context) => context.widthUnit * 4.5;\n\n  static double fontXs(BuildContext context) => context.heightUnit * 1.4;\n  static double fontSm(BuildContext context) => context.heightUnit * 1.6;\n  static double fontMd(BuildContext context) => context.heightUnit * 1.8;\n  static double fontLg(BuildContext context) => context.heightUnit * 2.0;\n  static double fontXl(BuildContext context) => context.heightUnit * 2.4;\n\n  static double bannerHeight(BuildContext context) =>\n      ContextExtensionss(context).isPortrait ? context.screenHeight * 0.16 : context.screenHeight * 0.32;\n\n  static double productCardWidth(BuildContext context) =>\n      context.screenWidth * (ContextExtensionss(context).isPortrait ? 0.42 : 0.28);\n\n  static double productCardHeight(BuildContext context) =>\n      ContextExtensionss(context).isPortrait ? context.screenHeight * 0.24 : context.screenHeight * 0.42;\n\n  static double categoryTileHeight(BuildContext context) =>\n      ContextExtensionss(context).isPortrait ? context.screenHeight * 0.08 : context.screenHeight * 0.14;\n\n  static double searchBarHeight(BuildContext context) =>\n      ContextExtensionss(context).isPortrait ? context.screenHeight * 0.055 : context.screenHeight * 0.1;\n}\n"
  },
  {
    "path": "lib\\core\\constants\\app_images.dart",
    "description": "Asset constants; register images or icons required by the next screen.",
    "content": "class AppImages {\n  AppImages._();\n\n  static const String base = 'assets/images';\n\n  static const String appLogo = '$base/app_logo.png';\n  static const String background = '$base/background_image.png';\n  static const String loginBackground = '$base/login_background.png';\n\n  static const String avacado = '$base/avacado_image.png';\n  static const String onion = '$base/onion_image.png';\n  static const String cabbage = '$base/cabbage_image.png';\n  static const String tortilla = '$base/tortilla_image.png';\n  static const String peanuts = '$base/peanuts_jmage.png';\n\n  static const String featured1 = '$base/featured_card_1.png';\n  static const String featured2 = '$base/featured_card_2.png';\n  static const String editors1 = '$base/editors_choice1.png';\n  static const String editors2 = '$base/editors_choice2.png';\n\n  static const String search = '$base/search_icon.png';\n  static const String cart = '$base/cart_icon.png';\n  static const String fav = '$base/favourite_icon.png';\n  static const String settings = '$base/settings_icon.png';\n  static const String forward = '$base/forward_icon.png';\n  static const String sun = '$base/sun_icon.png';\n  static const String chef = '$base/chef_icon.png';\n\n  static const String bottomHome = '$base/bottom_home_icon.png';\n  static const String bottomSearch = '$base/bottom_search_icon.png';\n  static const String bottomNotifications = '$base/bottom_notifications_icon.png';\n  static const String bottomProfile = '$base/bottom_profile_icon.png';\n\n  static const String increament = '$base/increament_icon.png';\n  static const String decreament = '$base/decreament_icon.png';\n\n  static const String proteins = '$base/proteins_icon.png';\n  static const String fats = '$base/fats_icon.png';\n  static const String carbs = '$base/carbs_icon.png';\n  static const String calories = '$base/calories_icon.png';\n\n  static const String user1 = '$base/user_image_1.png';\n  static const String user2 = '$base/user_image_2.png';\n  static const String natalia = '$base/natalia_luca_profile_pic.png';\n  static const String appBG = '$base/login_background.png';\n  static const String popular1 = '$base/popular_recipe1.png';\n  static const String popular2 = '$base/popular_recipe2.png';\n  static const String popular3 = '$base/popular_recipe3.png';\n  static const String popular4 = '$base/popular_recipe4.png';\n}\n"
