  {
    "path": "lib\\core\\constants\\app_strings.dart",
    "description": "Text constants; add titles and labels for the next screen.",
    "content": "class AppStrings {\n  AppStrings._();\n\n  static const String appTitle = 'Groceries';\n  static const String home = 'Home';\n  static const String explore = 'Explore';\n  static const String cart = 'Cart';\n  static const String favourite = 'Favourite';\n  static const String account = 'Account';\n\n  static const String location = 'Dhaka, Banassre';\n  static const String searchPlaceholder = 'Search Store';\n\n  static const String freshVegetables = 'Fresh Vegetables';\n  static const String getUpTo40 = 'Get Up To 40% OFF';\n\n  static const String exclusiveOffer = 'Exclusive Offer';\n  static const String bestSelling = 'Best Selling';\n  static const String seeAll = 'See all';\n\n  static const String groceries = 'Groceries';\n  static const String pulses = 'Pulses';\n  static const String rice = 'Rice';\n\n  static const String priceUnitKg = '1kg, Priceg';\n  static const String priceUnit7pcs = '7pcs, Priceg';\n  static const String priceUnit250g = '250gm, Priceg';\n}\n"
  },
  {
    "path": "lib\\core\\routing\\app_pages.dart",
    "description": "Central GetX routing; add a GetPage for the next screen and expose its route.",
    "content": "import 'package:get/get.dart';\nimport 'package:demo_app_2/modules/home/views/combined_screens.dart';\n\nclass Routes {\n  Routes._();\n  static const String combined = '/';\n}\n\nclass AppPages {\n  AppPages._();\n\n  static const String initial = Routes.combined;\n\n  static final pages = <GetPage>[\n    GetPage(name: Routes.combined, page: () => const CombinedScreens()),\n  ];\n}\n"
  },
  {
    "path": "lib\\core\\theme\\app_theme.dart",
    "description": "Global ThemeData; extend text styles and components for the next screen.",
    "content": "import 'package:flutter/material.dart';\nimport 'package:demo_app_2/core/constants/app_colors.dart';\n\nclass AppTheme {\n  AppTheme._();\n\n  static ThemeData get light {\n    final base = ThemeData.light(useMaterial3: false);\n    return base.copyWith(\n      scaffoldBackgroundColor: AppColors.background,\n      primaryColor: AppColors.primary,\n      colorScheme: base.colorScheme.copyWith(\n        primary: AppColors.primary,\n        secondary: AppColors.accentGreen,\n        surface: AppColors.surface,\n      ),\n      textTheme: base.textTheme.apply(\n        bodyColor: AppColors.textPrimary,\n        displayColor: AppColors.textPrimary,\n        fontFamily: 'SofiaPro',\n      ),\n      appBarTheme: const AppBarTheme(\n        elevation: 0,\n        backgroundColor: AppColors.background,\n        foregroundColor: AppColors.textPrimary,\n      ),\n      inputDecorationTheme: InputDecorationTheme(\n        isDense: true,\n        filled: true,\n        fillColor: const Color(0xFFF1F2F2),\n        border: OutlineInputBorder(\n          borderRadius: BorderRadius.circular(12),\n          borderSide: BorderSide.none,\n        ),\n      ),\n    );\n  }\n}\n"
  },
  {
    "path": "lib\\core\\utils\\context_extensions.dart",
    "description": "Context utilities; reuse for responsiveness on the next screen.",
    "content": "import 'package:flutter/material.dart';\n\nextension ContextExtensions on BuildContext {\n  double get screenWidth => MediaQuery.of(this).size.width;\n  double get screenHeight => MediaQuery.of(this).size.height;\n  double get widthUnit => screenWidth / 100;\n  double get heightUnit => screenHeight / 100;\n}\n\nclass ContextExtensionss {\n  final BuildContext context;\n  ContextExtensionss(this.context);\n  bool get isPortrait => MediaQuery.of(context).orientation == Orientation.portrait;\n  bool get isLandscape => !isPortrait;\n}\n"
  },
  {
    "path": "lib\\shared\\widgets\\app_bottom_nav.dart",
    "description": "Bottom navigation bar; add a tab or navigate to the next screen on item tap.",
    "content": "import 'package:flutter/material.dart';\nimport 'package:get/get.dart';\nimport 'package:demo_app_2/core/constants/app_colors.dart';\nimport 'package:demo_app_2/core/constants/app_dimensions.dart';\nimport 'package:demo_app_2/core/constants/app_images.dart';\nimport 'package:demo_app_2/core/constants/app_strings.dart';\nimport 'package:demo_app_2/core/utils/context_extensions.dart';\nimport 'package:demo_app_2/modules/home/controllers/home_controller.dart';\n\nclass AppBottomNav extends StatelessWidget {\n  const AppBottomNav({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    final c = Get.find<HomeController>();\n    final itemPadding = EdgeInsets.symmetric(vertical: AppDimensions.spacingXs(context));\n    return Obx(\n      () => Container(\n        decoration: const BoxDecoration(color: Colors.white, boxShadow: [\n          BoxShadow(color: Color(0x172A2A2A), offset: Offset(0, -6), blurRadius: 12),\n        ]),\n        child: SafeArea(\n          top: false,\n          child: Padding(\n            padding: EdgeInsets.symmetric(horizontal: AppDimensions.spacingLg(context)),\n            child: Row(\n              mainAxisAlignment: MainAxisAlignment.spaceBetween,\n              children: [\n                _Item(\n                  selected: c.tabIndex.value == 0,\n                  label: AppStrings.home,\n                  icon: AppImages.bottomHome,\n                  onTap: () => c.setTab(0),\n                  selectedColor: AppColors.accentGreen,\n                ),\n                _Item(\n                  selected: c.tabIndex.value == 1,\n                  label: AppStrings.explore,\n                  icon: AppImages.bottomSearch,\n                  onTap: () => c.setTab(1),\n                  selectedColor: AppColors.textPrimary,\n                ),\n                _Item(\n                  selected: c.tabIndex.value == 2,\n                  label: AppStrings.cart,\n                  icon: AppImages.cart,\n                  onTap: () => c.setTab(2),\n                  selectedColor: AppColors.textPrimary,\n                ),\n                _Item(\n                  selected: c.tabIndex.value == 3,\n                  label: AppStrings.favourite,\n                  icon: AppImages.fav,\n                  onTap: () => c.setTab(3),\n                  selectedColor: AppColors.textPrimary,\n                ),\n                _Item(\n                  selected: c.tabIndex.value == 4,\n                  label: AppStrings.account,\n                  icon: AppImages.bottomProfile,\n                  onTap: () => c.setTab(4),\n                  selectedColor: AppColors.textPrimary,\n                ),\n              ]\n                  .map((w) => Padding(padding: itemPadding, child: w))\n                  .toList(growable: false),\n            ),\n          ),\n        ),\n      ),\n    );\n  }\n}\n\nclass _Item extends StatelessWidget {\n  final bool selected;\n  final String label;\n  final String icon;\n  final VoidCallback onTap;\n  final Color selectedColor;\n\n  const _Item({\n    required this.selected,\n    required this.label,\n    required this.icon,\n    required this.onTap,\n    required this.selectedColor,\n  });\n\n  @override\n  Widget build(BuildContext context) {\n    final iconSize = context.widthUnit * 6.5;\n    return Column(\n      mainAxisSize: MainAxisSize.min,\n      children: [\n        Material(\n          color: selected ? AppColors.accentGreen : Colors.transparent,\n          shape: const CircleBorder(),\n          clipBehavior: Clip.antiAlias,\n          child: InkWell(\n            onTap: onTap,\n            child: Padding(\n              padding: EdgeInsets.all(context.widthUnit * 2.0),\n              child: Image.asset(\n                icon,\n                width: iconSize,\n                height: iconSize,\n                fit: BoxFit.contain,\n                color: selected ? Colors.white : null,\n              ),\n            ),\n          ),\n        ),\n        SizedBox(height: context.heightUnit * 0.8),\n        Text(\n          label,\n          style: TextStyle(\n            fontWeight: selected ? FontWeight.bold : FontWeight.w600,\n            fontSize: AppDimensions.fontSm(context),\n            color: selected ? AppColors.accentGreen : AppColors.navInactive,\n          ),\n        ),\n      ],\n    );\n  }\n}\n"
  },
  {
    "path": "lib\\shared\\widgets\\card_product_item.dart",
    "description": "Reusable product card; reuse or configure on the next screen product list.",
    "content": "import 'package:flutter/material.dart';\nimport 'package:demo_app_2/core/constants/app_colors.dart';\nimport 'package:demo_app_2/core/constants/app_dimensions.dart';\nimport 'package:demo_app_2/shared/widgets/round_icon_button.dart';\n\nclass CardProductItem extends StatelessWidget {\n  final String image;\n  final String title;\n  final String subtitle;\n  final double price;\n  final VoidCallback onAddToCart;\n  final bool enabled;\n  final EdgeInsetsGeometry? margin;\n\n  const CardProductItem({super.key, required this.image, required this.title, required this.subtitle, required this.price, required this.onAddToCart, this.enabled = true, this.margin});\n\n  @override\n  Widget build(BuildContext context) {\n    final w = AppDimensions.productCardWidth(context);\n    final h = AppDimensions.productCardHeight(context);\n    final radius = AppDimensions.radiusMd(context);\n\n    return Container(\n      width: w,\n      height: h,\n      margin: margin,\n      decoration: BoxDecoration(\n        color: Colors.white,\n        borderRadius: BorderRadius.circular(radius),\n        border: Border.all(color: AppColors.border),\n        boxShadow: const [\n          BoxShadow(color: AppColors.cardShadow, blurRadius: 12, offset: Offset(0, 6)),\n        ],\n      ),\n      child: Column(\n        crossAxisAlignment: CrossAxisAlignment.start,\n        children: [\n          SizedBox(height: AppDimensions.spacingSm(context)),\n          Expanded(\n            child: Center(\n              child: Image.asset(image, fit: BoxFit.contain),\n            ),\n          ),\n          Padding(\n            padding: EdgeInsets.symmetric(horizontal: AppDimensions.spacingSm(context)),\n            child: Column(\n              crossAxisAlignment: CrossAxisAlignment.start,\n              children: [\n                Text(\n                  title,\n                  maxLines: 1,\n                  overflow: TextOverflow.ellipsis,\n                  style: TextStyle(\n                    fontSize: AppDimensions.fontMd(context),\n                    fontWeight: FontWeight.w600,\n                    color: AppColors.textPrimary,\n                  ),\n                ),\n                SizedBox(height: AppDimensions.spacingXs(context) * 0.6),\n                Text(\n                  subtitle,\n                  style: TextStyle(\n                    fontSize: AppDimensions.fontSm(context),\n                    color: AppColors.textSecondary,\n                    fontWeight: FontWeight.w500,\n                  ),\n                ),\n                SizedBox(height: AppDimensions.spacingSm(context)),\n                Row(\n                  children: [\n                    Text(\n                      '\\$${price.toStringAsFixed(2)}',\n                      style: TextStyle(\n                        fontSize: AppDimensions.fontLg(context),\n                        fontWeight: FontWeight.w700,\n                        color: AppColors.textPrimary,\n                      ),\n                    ),\n                    const Spacer(),\n                    RoundIconButton(\n                      icon: const Icon(Icons.add, color: Colors.white),\n                      onTap: onAddToCart,\n                      enabled: enabled,\n                    ),\n                  ],\n                ),\n                SizedBox(height: AppDimensions.spacingSm(context)),\n              ],\n            ),\n          ),\n        ],\n      ),\n    );\n  }\n}\n"
  },
  {
    "path": "lib\\shared\\widgets\\round_icon_button.dart",
    "description": "Circular icon button; reuse for actions on the next screen.",
    "content": "import 'package:flutter/material.dart';\nimport 'package:demo_app_2/core/constants/app_colors.dart';\nimport 'package:demo_app_2/core/constants/app_dimensions.dart';\n\nclass RoundIconButton extends StatelessWidget {\n  final Widget icon;\n  final VoidCallback onTap;\n  final bool enabled;\n  final Color backgroundColor;\n  const RoundIconButton({super.key, required this.icon, required this.onTap, this.enabled = true, this.backgroundColor = AppColors.accentGreen});\n\n  @override\n  Widget build(BuildContext context) {\n    final size = AppDimensions.spacingXl(context);\n    return Material(\n      color: enabled ? backgroundColor : backgroundColor.withOpacity(0.4),\n      shape: const CircleBorder(),\n      clipBehavior: Clip.antiAlias,\n      child: InkWell(\n        onTap: enabled ? onTap : null,\n        child: SizedBox(\n          width: size,\n          height: size,\n          child: Center(child: icon),\n        ),\n      ),\n    );\n  }\n}\n"
  },
  {
    "path": "lib\\shared\\widgets\\search_bar.dart",
    "description": "Standard search input; reuse for searching on the next screen.",
    "content": "import 'package:flutter/material.dart';\nimport 'package:get/get.dart';\nimport 'package:demo_app_2/core/constants/app_dimensions.dart';\nimport 'package:demo_app_2/core/constants/app_images.dart';\nimport 'package:demo_app_2/modules/home/controllers/home_controller.dart';\n\nclass SearchBar extends StatelessWidget {\n  final String placeholder;\n  final ValueChanged<String> onChanged;\n  final VoidCallback? onClear;\n  const SearchBar({super.key, required this.placeholder, required this.onChanged, this.onClear});\n\n  @override\n  Widget build(BuildContext context) {\n    final c = Get.find<HomeController>();\n    return SizedBox(\n      height: AppDimensions.searchBarHeight(context),\n      child: Row(\n        children: [\n          Expanded(\n            child: TextField(\n              controller: c.searchController,\n              onChanged: onChanged,\n              decoration: InputDecoration(\n                hintText: placeholder,\n                prefixIcon: Padding(\n                  padding: EdgeInsets.symmetric(horizontal: AppDimensions.spacingXs(context)),\n                  child: Image.asset(AppImages.search, fit: BoxFit.contain),\n                ),\n                prefixIconConstraints: BoxConstraints(\n                  minWidth: AppDimensions.spacingXl(context),\n                  minHeight: AppDimensions.spacingXl(context),\n                ),\n                suffixIcon: Obx(\n                  () => c.searchQuery.value.isEmpty\n                      ? const SizedBox.shrink()\n                      : Material(\n                          color: Colors.transparent,\n                          child: InkWell(\n                            borderRadius: BorderRadius.circular(20),\n                            onTap: () {\n                              c.searchController.clear();\n                              c.onSearchChanged('');\n                              onClear?.call();\n                            },\n                            child: const Icon(Icons.close, color: Colors.black54),\n                          ),\n                        ),\n                ),\n              ),\n            ),\n          ),\n        ],\n      ),\n    );\n  }\n}\n"
  },
  {
    "path": "lib\\shared\\widgets\\section_header.dart",
    "description": "Section header widget; reuse to title sections on the next screen.",
    "content": "import 'package:flutter/material.dart';\nimport 'package:demo_app_2/core/constants/app_colors.dart';\nimport 'package:demo_app_2/core/constants/app_dimensions.dart';\nimport 'package:demo_app_2/core/constants/app_strings.dart';\n\nclass SectionHeader extends StatelessWidget {\n  final String title;\n  final VoidCallback onSeeAll;\n  const SectionHeader({super.key, required this.title, required this.onSeeAll});\n\n  @override\n  Widget build(BuildContext context) {\n    final spacing = AppDimensions.spacingSm(context);\n    return Padding(\n      padding: EdgeInsets.symmetric(horizontal: spacing),\n      child: Row(\n        children: [\n          Expanded(\n            child: Text(\n              title,\n              style: TextStyle(\n                fontSize: AppDimensions.fontXl(context),\n                fontWeight: FontWeight.w600,\n                color: AppColors.textPrimary,\n              ),\n            ),\n          ),\n          Material(\n            color: Colors.transparent,\n            child: InkWell(\n              onTap: onSeeAll,\n              borderRadius: BorderRadius.circular(8),\n              child: Padding(\n                padding: EdgeInsets.all(AppDimensions.spacingXs(context)),\n                child: Text(\n                  AppStrings.seeAll,\n                  style: TextStyle(\n                    fontSize: AppDimensions.fontMd(context),\n                    fontWeight: FontWeight.w600,\n                    color: AppColors.accentGreen,\n                  ),\n                ),\n              ),\n            ),\n          ),\n        ],\n      ),\n    );\n  }\n}\n"
  },
  {
    "path": "lib\\modules\\home\\bindings\\home_binding.dart",
    "description": "Example binding; follow pattern to bind next screen controller.",
    "content": "import 'package:get/get.dart';\nimport 'package:demo_app_2/modules/home/controllers/home_controller.dart';\n\nclass HomeBinding extends Bindings {\n  @override\n  void dependencies() {\n    Get.lazyPut<HomeController>(() => HomeController(), fenix: true);\n  }\n}\n"
  },
  {
    "path": "lib\\modules\\home\\controllers\\home_controller.dart",
    "description": "App state and navigation helpers; add methods to open the next screen.",
    "content": "import 'package:flutter/material.dart';\nimport 'package:get/get.dart';\nimport 'package:demo_app_2/core/constants/app_images.dart';\nimport 'package:demo_app_2/core/constants/app_strings.dart';\nimport 'package:demo_app_2/modules/home/models/category.dart';\nimport 'package:demo_app_2/modules/home/models/product.dart';\nimport 'package:demo_app_2/modules/home/models/promo_banner.dart';\n\nclass HomeController extends GetxController {\n  final tabIndex = 0.obs;\n\n  final searchQuery = ''.obs;\n  final selectedCategoryId = RxnString();\n  final bannerIndex = 0.obs;\n\n  final cartCount = 0.obs;\n\n  final searchController = TextEditingController();\n\n  List<PromoBanner> get banners => const [\n        PromoBanner(\n          id: 'b1',\n          title: AppStrings.freshVegetables,\n          subtitle: AppStrings.getUpTo40,\n          image: AppImages.featured1,\n        ),\n        PromoBanner(\n          id: 'b2',\n          title: AppStrings.freshVegetables,\n          subtitle: AppStrings.getUpTo40,\n          image: AppImages.featured2,\n        ),\n      ];\n\n  List<Category> get categories => const [\n        Category(\n          id: 'pulses',\n          title: AppStrings.pulses,\n          image: AppImages.peanuts,\n          color: 0xFFF8A44C,\n        ),\n        Category(\n          id: 'rice',\n          title: AppStrings.rice,\n          image: AppImages.tortilla,\n          color: 0xFF53B175,\n        ),\n      ];\n\n  List<Product> get products => const [\n        Product(\n          id: 'p1',\n          name: 'Organic Bananas',\n          image: AppImages.avacado,\n          price: 4.99,\n          unitText: AppStrings.priceUnit7pcs,\n          categoryId: 'pulses',\n        ),\n        Product(\n          id: 'p2',\n          name: 'Red Apple',\n          image: AppImages.onion,\n          price: 4.99,\n          unitText: AppStrings.priceUnitKg,\n          categoryId: 'rice',\n        ),\n        Product(\n          id: 'p3',\n          name: 'Bell Pepper Red',\n          image: AppImages.cabbage,\n          price: 4.99,\n          unitText: AppStrings.priceUnitKg,\n          categoryId: 'pulses',\n        ),\n        Product(\n          id: 'p4',\n          name: 'Ginger',\n          image: AppImages.tortilla,\n          price: 4.99,\n          unitText: AppStrings.priceUnit250g,\n          categoryId: 'rice',\n        ),\n        Product(\n          id: 'p5',\n          name: 'Organic Bananas',\n          image: AppImages.avacado,\n          price: 4.99,\n          unitText: AppStrings.priceUnitKg,\n          categoryId: 'pulses',\n        ),\n        Product(\n          id: 'p6',\n          name: 'Beef Bone',\n          image: AppImages.featured1,\n          price: 4.99,\n          unitText: AppStrings.priceUnitKg,\n          categoryId: 'pulses',\n        ),\n        Product(\n          id: 'p7',\n          name: 'Broiler Chicken',\n          image: AppImages.featured2,\n          price: 4.99,\n          unitText: AppStrings.priceUnitKg,\n          categoryId: 'rice',\n        ),\n      ];\n\n  List<Product> get exclusiveOffers => products.take(3).toList(growable: false);\n  List<Product> get bestSelling => products.reversed.take(3).toList(growable: false);\n\n  List<Product> get meatAndPoultry => products.where((p) => p.name == 'Beef Bone' || p.name == 'Broiler Chicken').toList(growable: false);\n\n  List<Product> get filteredProducts {\n    final query = searchQuery.value.trim().toLowerCase();\n    final cat = selectedCategoryId.value;\n    return products.where((p) {\n      final matchesQuery = query.isEmpty || p.name.toLowerCase().contains(query);\n      final matchesCat = cat == null || p.categoryId == cat;\n      return matchesQuery && matchesCat;\n    }).toList(growable: false);\n  }\n\n  String get searchPlaceholder => AppStrings.searchPlaceholder;\n\n  void onSearchChanged(String value) {\n    searchQuery(value);\n  }\n\n  void selectCategory(String? id) {\n    if (selectedCategoryId.value == id) {\n      selectedCategoryId.value = null;\n    } else {\n      selectedCategoryId.value = id;\n    }\n  }\n\n  void addToCart(Product p) {\n    cartCount.value++;\n  }\n\n  void setTab(int index) {\n    tabIndex.value = index;\n  }\n\n  void onSeeAllExclusive() {}\n  void onSeeAllBestSelling() {}\n\n  void setBannerIndex(int index) {\n    bannerIndex.value = index;\n  }\n\n  @override\n  void onClose() {\n    searchController.dispose();\n    super.onClose();\n  }\n}\n"
